with enriched as (select id, carrier, cost, status, sum(cost) over w_hist as running_cost, last_value(cost, true) over w_hist_2 as last_known_cost, rank() over (partition by carrier order by cost) as cost_rank from shipments window w_hist as (order by cost, id rows between unbounded preceding and current row), w_hist_2 as (partition by carrier, status order by delivered_date, id rows between unbounded preceding and current row)) select id, running_cost from enriched;
